def csv_rows(name):
    with (OUT / name).open(encoding='utf-8-sig', newline='') as handle:
        return list(csv.DictReader(handle))


def pvalue(value):
    return f'{value:.2e}' if value < .001 else f'{value:.3f}'


def cell_text(cell, text, bold=False):
    cell.text = str(text)
    for p in cell.paragraphs:
        p.paragraph_format.space_after = Pt(4)
        p.paragraph_format.space_before = Pt(3)
        p.paragraph_format.line_spacing = 1.05
        for run in p.runs:
            run.font.size = Pt(10)
            run.bold = bold


def table(doc, headers, rows, widths):
    t = doc.add_table(rows=1, cols=len(headers))
    t.autofit = False
    for cell, text, width in zip(t.rows[0].cells, headers, widths):
        cell.width = Inches(width)
        cell_text(cell, text, True)
        shading = OxmlElement('w:shd'); shading.set(qn('w:fill'), 'EFEFEF');cell._tc.get_or_add_tcPr().append(shading)
    repeat = OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for row in rows:
        cells = t.add_row().cells
        for cell, text, width in zip(cells, row, widths):
            cell.width = Inches(width);cell_text(cell, text)
        prevent = OxmlElement('w:cantSplit');t.rows[-1]._tr.get_or_add_trPr().append(prevent)
    for column, width in zip(t.columns, widths):column.width = Inches(width)
    for index, row in enumerate(t.rows):
        if index == 0 or (len(rows) <= 7 and index < len(t.rows)-1):
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                    paragraph.paragraph_format.keep_with_next = True
    doc.add_paragraph().paragraph_format.space_after = Pt(1)
    return t


def caption(doc, text):
    p=doc.add_paragraph(text,'Caption');p.paragraph_format.keep_with_next=True
    return p


def figure(doc, filename, text):
    p=doc.add_paragraph();p.paragraph_format.keep_with_next=True
    p.add_run().add_picture(str(OUT/filename),width=Inches(6.35))
    p=doc.add_paragraph(text,'Caption');p.paragraph_format.keep_with_next=False


